with flattened as (select id, coupon_codes, key, v from carts lateral view outer explode(attributes) e as key, v), flattened_carts as (select id, v, explode(coupon_codes) as value from flattened), valid as (select *, case when value in ('VIP', 'SPRING10') then 'Priority' else 'Other' end value_group, coalesce(value, 'NONE') resolved_value from flattened_carts where value is null), base as (select v, value_group, resolved_value, substring(value, 1, 4) value_prefix, case when value = 'BUNDLE' then 1 else 0 end is_bundle, coalesce(value, 'DIRECT') value_filled from valid where value = 'SPRING10') select v, value_group, resolved_value, is_bundle, value_filled from base order by is_bundle desc;
